"use client";

import * as THREE from "three";
import { OrbitControls } from "three/addons/controls/OrbitControls.js";
import { EffectComposer } from "three/addons/postprocessing/EffectComposer.js";
import { RenderPass } from "three/addons/postprocessing/RenderPass.js";
import { UnrealBloomPass } from "three/addons/postprocessing/UnrealBloomPass.js";

// CONFIG
const COUNT = 5000;
const SPEED_MULT = 0.8;
const AUTO_SPIN = true;

// SETUP
const scene = new THREE.Scene();
scene.fog = new THREE.FogExp2(0x000000, 0.01);
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  2000,
);
camera.position.set(0, 0, 100);

const renderer = new THREE.WebGLRenderer({
  antialias: true,
  powerPreference: "high-performance",
});
renderer.setSize(window.innerWidth, window.innerHeight);
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.autoRotate = AUTO_SPIN;
controls.autoRotateSpeed = 2.0;

// POST PROCESSING
const composer = new EffectComposer(renderer);
composer.addPass(new RenderPass(scene, camera));
const bloomPass = new UnrealBloomPass(
  new THREE.Vector2(window.innerWidth, window.innerHeight),
  1.5,
  0.4,
  0.85,
);
bloomPass.strength = 1.8;
bloomPass.radius = 0.4;
bloomPass.threshold = 0;
composer.addPass(bloomPass);

// SWARM OBJECTS
const dummy = new THREE.Object3D();
const color = new THREE.Color();
const target = new THREE.Vector3();
const pColor = new THREE.Color(); // Kept for safety, for potential references

// INSTANCED MESH
const geometry = new THREE.TetrahedronGeometry(0.25);
const material = new THREE.MeshBasicMaterial({ color: 0xffffff });

const instancedMesh = new THREE.InstancedMesh(geometry, material, COUNT);
instancedMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
scene.add(instancedMesh);

// DATA ARRAYS
const positions = [];
for (let i = 0; i < COUNT; i++) {
  positions.push(
    new THREE.Vector3(
      (Math.random() - 0.5) * 100,
      (Math.random() - 0.5) * 100,
      (Math.random() - 0.5) * 100,
    ),
  );
  instancedMesh.setColorAt(i, color.setHex(0x00ff88)); // Init Color
}

// CONTROL STUBS
const PARAMS = {};
const addControl = (id, label, min, max, val) => {
  return PARAMS[id] !== undefined ? PARAMS[id] : val;
};
const setInfo = () => {};
const annotate = () => {};

